import json
import time
from typing import Tuple
from ruamel.yaml import CommentedMap
from app.core.config import settings
from app.helper.ocr import OcrHelper
from app.log import logger
from app.plugins.autosignin.sites import _ISiteSigninHandler
from app.utils.http import RequestUtils
from app.utils.string import StringUtils

class HDSky(_ISiteSigninHandler):
    """
    天空ocr签到
    """
    site_url = 'hdsky.me'
    _sign_regex = ['已签到']

    @classmethod
    def match(cls, url: str) -> bool:
        """
        根据站点Url判断是否匹配当前站点签到类，大部分情况使用默认实现即可
        :param url: 站点Url
        :return: 是否匹配，如匹配则会调用该类的signin方法
        """
        return True if StringUtils.url_equal(url, cls.site_url) else False

    def signin(self, site_info: CommentedMap) -> Tuple[bool, str]:
        """
        执行签到操作
        :param site_info: 站点信息，含有站点Url、站点Cookie、UA等信息
        :return: 签到结果信息
        """
        site = site_info.get('name')
        site_cookie = site_info.get('cookie')
        ua = site_info.get('ua')
        proxy = site_info.get('proxy')
        render = site_info.get('render')
        referer = site_info.get('url')
        timeout = site_info.get('timeout')
        html_text = self.get_page_source(url='https://hdsky.me', cookie=site_cookie, ua=ua, proxy=proxy, render=render, timeout=timeout)
        if not html_text:
            logger.error(f'{site} 签到失败，请检查站点连通性')
            return (False, '签到失败，请检查站点连通性')
        if 'login.php' in html_text:
            logger.error(f'{site} 签到失败，Cookie已失效')
            return (False, '签到失败，Cookie已失效')
        sign_status = self.sign_in_result(html_res=html_text, regexs=self._sign_regex)
        if sign_status:
            logger.info(f'{site} 今日已签到')
            return (True, '今日已签到')
        res_times = 0
        img_hash = None
        while not img_hash and res_times <= 3:
            image_res = RequestUtils(cookies=site_cookie, ua=ua, content_type='application/x-www-form-urlencoded; charset=UTF-8', referer='https://hdsky.me/index.php', accept_type='*/*', proxies=settings.PROXY if proxy else None, timeout=timeout).post_res(url='https://hdsky.me/image_code_ajax.php', data={'action': 'new'})
            if image_res and image_res.status_code == 200:
                image_json = json.loads(image_res.text)
                if image_json.get('success') is True:
                    img_hash = image_json['code']
                    break
                res_times += 1
                logger.info(f'获取 {site} 验证码失败，正在进行重试，目前重试次数：{res_times}')
                time.sleep(1)
        if img_hash:
            img_get_url = 'https://hdsky.me/image.php?action=regimage&imagehash=%s' % img_hash
            logger.info(f'获取到 {site} 验证码链接：{img_get_url}')
            times = 0
            ocr_result = None
            while times <= 3:
                ocr_result = OcrHelper().get_captcha_text(image_url=img_get_url, cookie=site_cookie, ua=ua)
                logger.info(f'OCR识别 {site} 验证码：{ocr_result}')
                if ocr_result:
                    if len(ocr_result) == 6:
                        logger.info(f'OCR识别 {site} 验证码成功：{ocr_result}')
                        break
                times += 1
                logger.info(f'OCR识别 {site} 验证码失败，正在进行重试，目前重试次数：{times}')
                time.sleep(1)
            if ocr_result:
                data = {'action': 'showup', 'imagehash': img_hash, 'imagestring': ocr_result}
                res = RequestUtils(cookies=site_cookie, ua=ua, referer=referer, proxies=settings.PROXY if proxy else None).post_res(url='https://hdsky.me/showup.php', data=data)
                if res and res.status_code == 200:
                    if json.loads(res.text).get('success') is True:
                        logger.info(f'{site} 签到成功')
                        return (True, '签到成功')
                    elif str(json.loads(res.text)['message']) == 'date_unmatch':
                        logger.warn(f'{site} 重复成功')
                        return (True, '今日已签到')
                    elif str(json.loads(res.text)['message']) == 'invalid_imagehash':
                        logger.warn(f'{site} 签到失败：验证码错误')
                        return (False, '签到失败：验证码错误')
        logger.error(f'{site} 签到失败：未获取到验证码')
        return (False, '签到失败：未获取到验证码')

