    @classmethod
    def match(cls, url: str) -> bool:
        """
        根据站点Url判断是否匹配当前站点签到类，大部分情况使用默认实现即可
        :param url: 站点Url
        :return: 是否匹配，如匹配则会调用该类的signin方法
        """
        return True if StringUtils.url_equal(url, cls.site_url) else False

    def signin(self, site_info: CommentedMap) -> Tuple[bool, str]:
        """
        执行签到操作
        :param site_info: 站点信息，含有站点Url、站点Cookie、UA等信息
        :return: 签到结果信息
        """
        site = site_info.get('name')
        site_cookie = site_info.get('cookie')
        ua = site_info.get('ua')
        proxy = site_info.get('proxy')
        render = site_info.get('render')
        timeout = site_info.get('timeout')
        html_text = self.get_page_source(url='https://www.open.cd', cookie=site_cookie, ua=ua, proxy=proxy, render=render, timeout=timeout)
        if not html_text:
            logger.error(f'{site} 签到失败，请检查站点连通性')
            return (False, '签到失败，请检查站点连通性')
        if 'login.php' in html_text:
            logger.error(f'{site} 签到失败，Cookie已失效')
            return (False, '签到失败，Cookie已失效')
        if has_signin_evidence(html_text):
            logger.info(f'{site} 今日已签到')
            return (True, '今日已签到')
        html_text = self.get_page_source(url='https://www.open.cd/plugin_sign-in.php', cookie=site_cookie, ua=ua, proxy=proxy, render=render)
        if not html_text:
            logger.error(f'{site} 签到失败，请检查站点连通性')
            return (False, '签到失败，请检查站点连通性')
        html = etree.HTML(html_text)
        if html is None:
            return (False, '签到失败')
        img_url = html.xpath('//form[@id="frmSignin"]//img/@src')[0]
        img_hash = html.xpath('//form[@id="frmSignin"]//input[@name="imagehash"]/@value')[0]
        if not img_url or not img_hash:
            logger.error(f'{site} 签到失败，获取签到参数失败')
            return (False, '签到失败，获取签到参数失败')
        img_get_url = 'https://www.open.cd/%s' % img_url
        logger.debug(f'{site} 获取到{site}验证码链接 {img_get_url}')
        times = 0
        ocr_result = None
        while times <= 3:
            ocr_result = OcrHelper().get_captcha_text(image_url=img_get_url, cookie=site_cookie, ua=ua)
            logger.debug(f'ocr识别{site}验证码 {ocr_result}')
            if ocr_result:
                if len(ocr_result) == 6:
                    logger.info(f'ocr识别{site}验证码成功 {ocr_result}')
                    break
            times += 1
            logger.debug(f'ocr识别{site}验证码失败，正在进行重试，目前重试次数 {times}')
            time.sleep(1)
        if ocr_result:
            data = {'imagehash': img_hash, 'imagestring': ocr_result}
            sign_res = RequestUtils(cookies=site_cookie, ua=ua, proxies=settings.PROXY if proxy else None).post_res(url='https://www.open.cd/plugin_sign-in.php?cmd=signin', data=data)
            if sign_res and sign_res.status_code == 200:
                logger.debug(f'sign_res返回 {sign_res.text}')
                sign_dict = json.loads(sign_res.text)
                if sign_dict.get('state') == 'success':
                    logger.info(f'{site} 签到成功')
                    return (True, '签到成功')
                else:
                    logger.error(f'{site} 签到失败，签到接口返回 {sign_dict}')
                    return (False, '签到失败')
        logger.error(f'{site} 签到失败：未获取到验证码')
        return (False, '签到失败：未获取到验证码')

