import datetime
import random
import re
from typing import Tuple
from urllib.parse import urljoin, urlparse
from lxml import etree
from ruamel.yaml import CommentedMap
from app.core.config import settings
from app.log import logger
from app.plugins.autosignin.sites import _ISiteSigninHandler
from app.utils.http import RequestUtils
from app.utils.site import SiteUtils
from app.utils.string import StringUtils

class U2(_ISiteSigninHandler):
    """
    U2签到 随机
    """
    site_url = 'u2.dmhy.org'
    _sign_regex = ['<a href="showup.php">已签到</a>', '<a href="showup.php">Show Up</a>', '<a href="showup.php">Показать</a>', '<a href="showup.php">已簽到</a>', '<a href="showup.php">已簽到</a>']
    _success_redirect_regex = re.compile('window\\s*\\.\\s*location\\s*\\.\\s*href\\s*=\\s*[\'\\"]([^\'\\"]+)[\'\\"]')

    @classmethod
    def _is_success_response(cls, response_text: str) -> bool:
        """识别需要回读的签到页跳转；跳转本身不作为签到成功凭据。"""
        match = cls._success_redirect_regex.search(response_text)
        if not match:
            return False
        target = urlparse(urljoin('https://u2.dmhy.org/showup.php', match.group(1)))
        return target.netloc.casefold() == cls.site_url and target.path == '/showup.php'

    @classmethod
    def _has_signed_state(cls, html_text: str) -> bool:
        """已登录且显示完成状态时确认签到，仍含答题参数的页面不能确认。"""
        if not html_text or not SiteUtils.is_logged_in(html_text):
            return False
        html = etree.HTML(html_text)
        return not html.xpath('//input[@name="req"] | //form[contains(@action, "showup.php")]') and cls.sign_in_result(html_text, cls._sign_regex)

    @classmethod
    def match(cls, url: str) -> bool:
        """
        根据站点Url判断是否匹配当前站点签到类，大部分情况使用默认实现即可
        :param url: 站点Url
        :return: 是否匹配，如匹配则会调用该类的signin方法
        """
        return True if StringUtils.url_equal(url, cls.site_url) else False

    def signin(self, site_info: CommentedMap) -> Tuple[bool, str]:
        """
        执行签到操作
        :param site_info: 站点信息，含有站点Url、站点Cookie、UA等信息
        :return: 签到结果信息
        """
        site = site_info.get('name')
        site_cookie = site_info.get('cookie')
        ua = site_info.get('ua')
        proxy = site_info.get('proxy')
        render = site_info.get('render')
        timeout = site_info.get('timeout')
        now = datetime.datetime.now()
        if now.hour < 9:
            logger.error(f'{site} 签到失败，9点前不签到')
            return (False, '签到失败，9点前不签到')
        html_text = self.get_page_source(url='https://u2.dmhy.org/showup.php', cookie=site_cookie, ua=ua, proxy=proxy, render=render, timeout=timeout)
        if not html_text:
            logger.error(f'{site} 签到失败，请检查站点连通性')
            return (False, '签到失败，请检查站点连通性')
        if not SiteUtils.is_logged_in(html_text):
            logger.error(f'{site} 签到失败，Cookie已失效')
            return (False, '签到失败，Cookie已失效')
        sign_status = self._has_signed_state(html_text)
        if sign_status:
            logger.info(f'{site} 今日已签到')
            return (True, '今日已签到')
        html = etree.HTML(html_text)
        if html is None:
            return (False, '签到失败')
        req = html.xpath("//form//input[@name='req']/@value")
        hash_str = html.xpath("//form//input[@name='hash']/@value")
        form = html.xpath("//form//input[@name='form']/@value")
        csrf_token = html.xpath("//form//input[@name='_csrf']/@value")
        submit_name = html.xpath("//form//td/input[@type='submit']/@name")
        submit_value = html.xpath("//form//td/input[@type='submit']/@value")
        if not req or not hash_str or (not form) or (not csrf_token) or (not submit_name) or (not submit_value):
            logger.error(f'{site} 签到失败，未获取到相关签到参数')
            return (False, '签到失败')
        answer_num = random.randint(0, 3)
        data = {'req': req[0], 'hash': hash_str[0], 'form': form[0], '_csrf': csrf_token[0], 'message': '一切随缘~', submit_name[answer_num]: submit_value[answer_num]}
        sign_res = RequestUtils(cookies=site_cookie, ua=ua, proxies=settings.PROXY if proxy else None, headers={'User-Agent': ua, 'Referer': 'https://u2.dmhy.org/showup.php', 'Origin': 'https://u2.dmhy.org'}).post_res(url='https://u2.dmhy.org/showup.php?action=show', data=data)
        if not sign_res or sign_res.status_code != 200:
            logger.error(f'{site} 签到失败，签到接口请求失败')
            return (False, '签到失败，签到接口请求失败')
        if self._is_success_response(sign_res.text):
            checked_page = self.get_page_source(url='https://u2.dmhy.org/showup.php', cookie=site_cookie, ua=ua, proxy=proxy, render=render, timeout=timeout)
            if self._has_signed_state(checked_page):
                logger.info(f'{site} 签到成功')
                return (True, '签到成功')
        logger.error(f'{site} 签到失败，未确认签到结果')
        return (False, '签到失败，未确认签到结果')

