from typing import Tuple
from urllib.parse import urljoin
from ruamel.yaml import CommentedMap
from app.core.config import settings
from app.plugins.autosignin.sites import _ISiteSigninHandler
from app.utils.http import RequestUtils

class YemaPT(_ISiteSigninHandler):
    """
    YemaPT 签到
    """
    site_url = 'yemapt.org'

    @classmethod
    def match(cls, url: str) -> bool:
        """
        根据站点Url判断是否匹配当前站点签到类，大部分情况使用默认实现即可
        :param url: 站点Url
        :return: 是否匹配，如匹配则会调用该类的signin方法
        """
        return True if cls.site_url in url else False

    def signin(self, site_info: CommentedMap) -> Tuple[bool, str]:
        """
        执行签到操作
        :param site_info: 站点信息，含有站点Url、站点Cookie、UA等信息
        :return: 签到结果信息
        """
        headers = {'Content-Type': 'application/json', 'User-Agent': site_info.get('ua'), 'Accept': 'application/json, text/plain, */*'}
        res = RequestUtils(headers=headers, timeout=site_info.get('timeout'), cookies=site_info.get('cookie'), proxies=settings.PROXY if site_info.get('proxy') else None, referer=site_info.get('url')).get_res(urljoin(site_info.get('url'), 'api/consumer/checkIn'))
        if res is not None and res.status_code == 200 and (res.json().get('success') is True):
            return (True, '签到成功')
        elif res is not None:
            return (False, f"签到失败，签到结果：{res.json().get('errorMessage')}")
        else:
            return (False, '签到失败，无法打开网站')

    def login(self, site_info: CommentedMap) -> Tuple[bool, str]:
        """
        执行登录操作
        :param site_info: 站点信息，含有站点Url、站点Cookie、UA等信息
        :return: 登录结果信息
        """
        headers = {'Content-Type': 'application/json', 'User-Agent': site_info.get('ua'), 'Accept': 'application/json, text/plain, */*'}
        res = RequestUtils(headers=headers, timeout=site_info.get('timeout'), cookies=site_info.get('cookie'), proxies=settings.PROXY if site_info.get('proxy') else None, referer=site_info.get('url')).get_res(urljoin(site_info.get('url'), 'api/user/profile'))
        if res is not None and res.status_code == 200 and (res.json().get('success') is True):
            return (True, '模拟登录成功')
        elif res is not None:
            return (False, f'模拟登录失败，状态码：{res.status_code}')
        else:
            return (False, '模拟登录失败，无法打开网站')

methods.ModuleHelper.load:
@classmethod
def load(cls, package_path: str, filter_func: FilterFuncType=_default_filter) -> List[Any]:
    """
        导入模块
        :param package_path: 父包名
        :param filter_func: 子模块过滤函数，入参为模块名和模块对象，返回True则导入，否则不导入
        :return: 导入的模块对象列表
        """
    submodules: list = []
    loaded_modules = set()
    packages = importlib.import_module(package_path)
    for importer, package_name, _ in pkgutil.iter_modules(packages.__path__):
        try:
            if package_name.startswith('_'):
                continue
            full_package_name = f'{package_path}.{package_name}'
            module = importlib.import_module(full_package_name)
            importlib.reload(module)
            for name, obj in module.__dict__.items():
                if name.startswith('_'):
                    continue
                if isinstance(obj, type) and filter_func(name, obj):
                    if name in loaded_modules:
                        continue
                    loaded_modules.add(name)
                    submodules.append(obj)
        except Exception as err:
            logger.debug(f'加载模块 {package_name} 失败：{str(err)} - {traceback.format_exc()}')
    return submodules

methods.StringUtils.url_equal:
@staticmethod
def url_equal(url1: str, url2: str) -> bool:
    """
        比较两个地址是否为同一个网站
        """
    if not url1 or not url2:
        return False
    if url1.startswith('http'):
        url1 = parse.urlparse(url1).netloc
    if url2.startswith('http'):
        url2 = parse.urlparse(url2).netloc
    if url1.replace('www.', '') == url2.replace('www.', ''):
        return True
    return False

methods.StringUtils.get_url_netloc:
@staticmethod
def get_url_netloc(url: str) -> Tuple[str, str]:
    """
        获取URL的协议和域名部分
        """
    if not url:
        return ('', '')
    if not url.startswith('http'):
        return ('http', url)
    addr = parse.urlparse(url)
    return (addr.scheme, addr.netloc)

methods.StringUtils.get_url_domain:
@staticmethod
def get_url_domain(url: str) -> str:
    """
        获取URL的域名部分，只保留最后两级
        """
    if not url:
        return ''
    for domain in _special_domains:
        if domain in url:
            return domain
    _, netloc = StringUtils.get_url_netloc(url)
    if netloc:
        locs = netloc.split('.')
        if len(locs) > 3:
            return netloc
        return '.'.join(locs[-2:])
    return ''

methods.SiteUtils.is_logged_in:
@classmethod
def is_logged_in(cls, html_text: str) -> bool:
    """
        判断站点是否已经登陆
        :param html_text:
        :return:
        """
    html = etree.HTML(html_text)
    try:
        if not StringUtils.is_valid_html_element(html):
            return False
        if html.xpath("//input[@type='password']"):
            return False
        xpaths = ['//a[contains(@href, "logout") or contains(@data-url, "logout") or contains(@href, "mybonus")  or contains(@onclick, "logout") or contains(@href, "usercp") or contains(@lay-on, "logout")]', '//form[contains(@action, "logout")]', '//div[@class="user-info-side"]', '//a[@id="myitem"]']
        for xpath in xpaths:
            if html.xpath(xpath):
                return True
        return False
    finally:
        if html is not None:
            del html

