methods.SiteOper.success:
def success(self, domain: str, seconds: Optional[int]=None):
    """
        站点访问成功
        """
    lst_date = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    sta = SiteStatistic.get_by_domain(self._db, domain)
    if sta:
        note = dict(sta.note) if sta.note else {}
        avg_seconds = None
        if seconds is not None:
            note[lst_date] = seconds or 1
            avg_times = len(note.keys())
            if avg_times > 10:
                note = dict(sorted(note.items(), key=lambda x: x[0], reverse=True)[:10])
            avg_seconds = sum([v for v in note.values()]) // avg_times
        sta.update(self._db, {'success': sta.success + 1, 'seconds': avg_seconds or sta.seconds, 'lst_state': 0, 'lst_mod_date': lst_date, 'note': note})
    else:
        note = {}
        if seconds is not None:
            note = {lst_date: seconds or 1}
        SiteStatistic(domain=domain, success=1, fail=0, seconds=seconds or 1, lst_state=0, lst_mod_date=lst_date, note=note).create(self._db)

methods.SiteOper.fail:
def fail(self, domain: str):
    """
        站点访问失败
        """
    lst_date = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
    sta = SiteStatistic.get_by_domain(self._db, domain)
    if sta:
        sta.update(self._db, {'fail': sta.fail + 1, 'lst_state': 1, 'lst_mod_date': lst_date})
    else:
        SiteStatistic(domain=domain, success=0, fail=1, lst_state=1, lst_mod_date=lst_date).create(self._db)

methods.PluginManager.start:
def start(self, pid: Optional[str]=None):
    """
        启动加载插件
        :param pid: 插件ID，为空加载所有插件
        """

    def check_module(module: Any):
        """
            检查模块
            """
        if not hasattr(module, 'init_plugin') or not hasattr(module, 'plugin_name'):
            return False
        return True
    installed_plugins = SystemConfigOper().get(SystemConfigKey.UserInstalledPlugins) or []
    plugins = self._load_selective_plugins(pid, installed_plugins, check_module)
    plugins.sort(key=lambda x: x.plugin_order if hasattr(x, 'plugin_order') else 0)
    for plugin in plugins:
        plugin_id = plugin.__name__
        if pid and plugin_id != pid:
            continue
        try:
            if not self.__set_and_check_auth_level(plugin=plugin):
                if plugin_id in self._plugins:
                    self._plugins[plugin_id] = plugin
                continue
            self._plugins[plugin_id] = plugin
            plugin_obj = plugin()
            plugin_obj.init_plugin(self.get_plugin_config(plugin_id))
            self._running_plugins[plugin_id] = plugin_obj
            logger.info(f'加载插件：{plugin_id} 版本：{plugin_obj.plugin_version}')
            if plugin_obj.get_state():
                eventmanager.enable_event_handler(plugin)
            else:
                eventmanager.disable_event_handler(plugin)
        except Exception as err:
            logger.error(f'加载插件 {plugin_id} 出错：{str(err)} - {traceback.format_exc()}')
    self.clear_plugin_agent_tools_cache()

methods.PlaywrightHelper.get_page_source:
def get_page_source(self, url: str, cookies: Optional[str]=None, ua: Optional[str]=None, proxies: Optional[dict]=None, headless: Optional[bool]=False, timeout: Optional[int]=60) -> Optional[str]:
    """
        获取网页源码
        :param url: 网页地址
        :param cookies: cookies
        :param ua: user-agent
        :param proxies: 代理
        :param headless: 是否无头模式
        :param timeout: 超时时间
        """
    source = None
    if self.__browser_emulation() == 'flaresolverr':
        try:
            solution = self.__flaresolverr_request(url=url, cookies=cookies, proxy_config=proxies, timeout=timeout)
            if solution:
                return solution.get('response')
        except Exception as e:
            logger.error(f'FlareSolverr 获取源码失败: {str(e)}')
    try:
        context = None
        page = None
        try:
            context = self.__launch_cloakbrowser_context(headless=headless, user_agent=ua, proxies=proxies)
            page = context.new_page()
            if cookies:
                page.set_extra_http_headers({'cookie': cookies})
            page.goto(url)
            page.wait_for_load_state('networkidle', timeout=timeout * 1000)
            source = page.content()
        except Exception as e:
            logger.error(f'获取网页源码失败: {str(e)}')
            source = None
        finally:
            if page:
                page.close()
            if context:
                context.close()
    except Exception as e:
        logger.error(f'CloakBrowser初始化失败: {str(e)}')
    return source

methods.under_challenge:
def under_challenge(html_text: str):
    """
    Check if the page is under challenge
    :param html_text:
    :return:
    """
    if not html_text:
        return False
    page_title = PyQuery(html_text)('title').text()
    logger.debug('under_challenge page_title=' + page_title)
    for title in CHALLENGE_TITLES:
        if page_title.lower() == title.lower():
            return True
    for selector in CHALLENGE_SELECTORS:
        html_doc = PyQuery(html_text)
        if html_doc(selector):
            return True
    return False
